-- Nocturne Neovim config
-- Colourscheme + palette are generated by nocturne-kde/src/tools.py
-- Plugins are managed by lazy.nvim (installed automatically on first launch).

vim.g.mapleader = " "
vim.g.maplocalleader = " "

-- ── Options ───────────────────────────────────────────────
local o = vim.opt
o.number = true
o.relativenumber = true
o.cursorline = true
o.signcolumn = "yes"
o.termguicolors = true
o.mouse = "a"
o.clipboard = "unnamedplus"
o.undofile = true
o.ignorecase = true
o.smartcase = true
o.splitright = true
o.splitbelow = true
o.scrolloff = 8
o.sidescrolloff = 8
o.expandtab = true
o.shiftwidth = 2
o.tabstop = 2
o.smartindent = true
o.wrap = false
o.updatetime = 250
o.timeoutlen = 400
o.showmode = false
o.laststatus = 3
o.winborder = "rounded"
o.list = true
o.listchars = { tab = "» ", trail = "·", nbsp = "␣" }
o.fillchars = { eob = " ", fold = " ", foldopen = "\u{f078}", foldclose = "\u{f054}", foldsep = " " }
o.inccommand = "split"
o.confirm = true

vim.cmd.colorscheme("nocturne")

-- ── Keymaps ───────────────────────────────────────────────
local map = vim.keymap.set
map("n", "<Esc>", "<cmd>nohlsearch<CR>")
map("n", "<leader>w", "<cmd>write<CR>", { desc = "Save" })
map("n", "<leader>q", "<cmd>quit<CR>", { desc = "Quit" })
map("n", "<C-h>", "<C-w>h", { desc = "Window left" })
map("n", "<C-j>", "<C-w>j", { desc = "Window down" })
map("n", "<C-k>", "<C-w>k", { desc = "Window up" })
map("n", "<C-l>", "<C-w>l", { desc = "Window right" })
map("v", "J", ":m '>+1<CR>gv=gv", { desc = "Move selection down" })
map("v", "K", ":m '<-2<CR>gv=gv", { desc = "Move selection up" })
map("n", "-", "<cmd>Oil<CR>", { desc = "Open parent directory" })
map("n", "<leader>d", vim.diagnostic.open_float, { desc = "Line diagnostics" })

vim.diagnostic.config({
  virtual_text = { prefix = "●", spacing = 2 },
  severity_sort = true,
  float = { border = "rounded" },
  signs = { text = {
    [vim.diagnostic.severity.ERROR] = "\u{f057}",
    [vim.diagnostic.severity.WARN] = "\u{f071}",
    [vim.diagnostic.severity.INFO] = "\u{f05a}",
    [vim.diagnostic.severity.HINT] = "󰌵",
  } },
})

vim.api.nvim_create_autocmd("TextYankPost", {
  callback = function() vim.hl.on_yank({ higroup = "IncSearch", timeout = 180 }) end,
})

-- ── lazy.nvim bootstrap ───────────────────────────────────
local lazypath = vim.fn.stdpath("data") .. "/lazy/lazy.nvim"
if not vim.uv.fs_stat(lazypath) then
  vim.fn.system({ "git", "clone", "--filter=blob:none", "--branch=stable",
    "https://github.com/folke/lazy.nvim.git", lazypath })
end
vim.opt.rtp:prepend(lazypath)

local c = require("nocturne_palette")

require("lazy").setup({
  -- fuzzy finder: uses the same fzf / fd / rg / bat as the shell
  {
    "ibhagwan/fzf-lua",
    cmd = "FzfLua",
    opts = {
      winopts = { border = "rounded", preview = { border = "rounded", scrollbar = false } },
      fzf_colors = true,
      files = { cmd = "fd --type f --hidden --follow --exclude .git" },
    },
    keys = {
      { "<leader>f", "<cmd>FzfLua files<CR>", desc = "Find files" },
      { "<leader>/", "<cmd>FzfLua live_grep<CR>", desc = "Grep project" },
      { "<leader>b", "<cmd>FzfLua buffers<CR>", desc = "Buffers" },
      { "<leader>r", "<cmd>FzfLua oldfiles<CR>", desc = "Recent files" },
      { "<leader>h", "<cmd>FzfLua helptags<CR>", desc = "Help" },
      { "<leader>s", "<cmd>FzfLua lsp_document_symbols<CR>", desc = "Symbols" },
      { "<leader>g", "<cmd>FzfLua git_status<CR>", desc = "Git status" },
      { "<leader><leader>", "<cmd>FzfLua resume<CR>", desc = "Resume last picker" },
    },
  },

  -- statusline in Nocturne colours
  {
    "nvim-lualine/lualine.nvim",
    event = "VeryLazy",
    opts = function()
      local function mode(bg) return { a = { fg = c.crust, bg = bg, gui = "bold" }, b = { fg = bg, bg = c.surface }, c = { fg = c.subtext, bg = c.crust } } end
      return {
        options = {
          theme = {
            normal = mode(c.mint), insert = mode(c.blue), visual = mode(c.violet),
            replace = mode(c.red), command = mode(c.yellow),
            inactive = { a = { fg = c.muted, bg = c.crust }, b = { fg = c.muted, bg = c.crust }, c = { fg = c.muted, bg = c.crust } },
          },
          component_separators = "",
          section_separators = { left = "\u{e0b4}", right = "\u{e0b6}" },
          globalstatus = true,
        },
        sections = {
          lualine_a = { { "mode", separator = { left = "\u{e0b6}" } } },
          lualine_b = { "branch", "diff" },
          lualine_c = { { "filename", path = 1 }, "diagnostics" },
          lualine_x = { "filetype" },
          lualine_y = { "progress" },
          lualine_z = { { "location", separator = { right = "\u{e0b4}" } } },
        },
      }
    end,
  },

  { "lewis6991/gitsigns.nvim", event = "BufReadPre", opts = {
      signs = { add = { text = "▎" }, change = { text = "▎" }, delete = { text = "\u{f0da}" } } } },

  { "folke/which-key.nvim", event = "VeryLazy", opts = { preset = "modern", win = { border = "rounded" } } },

  { "stevearc/oil.nvim", lazy = false, opts = { view_options = { show_hidden = true } } },

  { "echasnovski/mini.nvim", event = "VeryLazy", config = function()
      require("mini.pairs").setup()
      require("mini.surround").setup()
      require("mini.indentscope").setup({ symbol = "│" })
      require("mini.icons").setup()
      require("mini.icons").mock_nvim_web_devicons()
    end },

  -- completion
  {
    "saghen/blink.cmp",
    version = "1.*",
    event = "InsertEnter",
    opts = {
      keymap = { preset = "default" },
      completion = {
        menu = { border = "rounded" },
        documentation = { auto_show = true, window = { border = "rounded" } },
        ghost_text = { enabled = true },
      },
      signature = { enabled = true, window = { border = "rounded" } },
    },
  },

  -- LSP: install servers with :Mason, they are enabled automatically
  { "mason-org/mason.nvim", cmd = "Mason", opts = { ui = { border = "rounded" } } },
  {
    "mason-org/mason-lspconfig.nvim",
    event = { "BufReadPre", "BufNewFile" },
    dependencies = { "mason-org/mason.nvim", "neovim/nvim-lspconfig", "saghen/blink.cmp" },
    opts = {},
    config = function(_, opts)
      require("mason").setup({ ui = { border = "rounded" } })
      require("mason-lspconfig").setup(opts)
      vim.lsp.config("*", { capabilities = require("blink.cmp").get_lsp_capabilities() })
      vim.api.nvim_create_autocmd("LspAttach", {
        callback = function(ev)
          local m = function(k, f, d) vim.keymap.set("n", k, f, { buffer = ev.buf, desc = d }) end
          m("gd", vim.lsp.buf.definition, "Go to definition")
          m("K", vim.lsp.buf.hover, "Hover")
          m("<leader>a", vim.lsp.buf.code_action, "Code action")
          m("<leader>n", vim.lsp.buf.rename, "Rename")
          m("<leader>F", function() vim.lsp.buf.format({ async = true }) end, "Format")
        end,
      })
    end,
  },
}, {
  install = { colorscheme = { "nocturne" } },
  ui = { border = "rounded" },
  change_detection = { notify = false },
})
